from pathlib import Path
items=[
('以学铸魂：让理论学习融入日常','理论学习不止于阅读，更在于联系实际、学思结合。建议从原文阅读、问题研讨、行动复盘三个环节入手，让每一次学习都有记录、有思考、有收获。','制定一周学习计划','每周选定一个主题，安排一次集中阅读与一次交流讨论。学习笔记可以围绕“我理解了什么、与我的学习科研有什么联系、下一步准备怎么做”展开。','把学习成果转化为行动','从身边的小问题入手，在服务同学、规范实验记录和提升协作效率中检验学习成效。'),
('支部共建：把组织活力转化为协作动力','支部共建可以从共同需求出发，让组织优势与学科资源互相连接。本文提供一份可复用的共建活动策划思路，供支部工作参考。','从需求清单开始','围绕科研互助、学业支持、实验室安全和志愿服务，分别梳理资源清单与需求清单，选择一个小切口确定活动主题。','让协作形成闭环','活动前明确分工与时间节点，活动中记录过程，活动后收集反馈。用可落实的任务清单延续交流成果。'),
('志愿服务：让一份微光温暖身边的人','志愿服务既是力所能及的付出，也是理解社会、增进协作的过程。参与服务时，应尊重服务对象，注重实际需求，避免形式化。','选择适合自己的服务','可以从校园引导、科普讲解、学习帮扶和社区便民服务等方向开始，根据时间与能力合理安排参与频次。','做好准备与复盘','服务前了解岗位要求，保护服务对象隐私；服务后记录遇到的问题和改进建议，让下一次服务更周到。'),
('科创报国：在严谨求实中追寻光的答案','光电学科的探索离不开扎实的基础和长期的积累。把个人成长与团队需要相连接，可以从每一份真实、完整、可复现的实验记录做起。','把求实写进实验过程','如实记录实验条件、参数与异常情况，主动复核数据来源，规范引用资料。面对不符合预期的结果，也应保留完整记录。','在协作中提升能力','开展跨年级经验交流，分享仪器使用规范和问题排查方法。让知识在团队中传递，让创新建立在可靠的基础之上。'),
('青年成长：在知行合一中找到奋进坐标','成长既需要远大的目标，也需要具体而持续的行动。可以从学习、实践与服务三个维度，为自己制定一份可执行的成长计划。','将目标拆解为小任务','把阶段目标拆成每周可以完成的事项，例如阅读一篇文献、参与一次交流、完成一项服务。根据实际进展及时调整。','用复盘积累成长经验','每月回顾一次自己的计划：哪些行动有效，哪些方法需要改变，哪些协作值得延续。把收获与同伴分享，在互助中共同进步。')]
q=['SET NAMES utf8mb4;','START TRANSACTION;']
esc=lambda s:s.replace("'","''")
for i,item in enumerate(items,1):
 title,intro,h1,p1,h2,p2=item;url=f'http://127.0.0.1:8080/uploads/banner-{i}.png';title='【示例专题】'+title
 html=f'<p><strong>示例内容说明：</strong>本文为本地演示专题，不代表已开展的真实活动。</p><p><img src="{url}" style="width:100%;height:auto" /></p><p>{intro}</p><h2>{h1}</h2><p>{p1}</p><h2>{h2}</h2><p>{p2}</p><p><strong>交流思考：</strong>结合自己的学习和工作，你准备从哪一件小事开始行动？</p>'
 q.append(f"INSERT INTO swiper(url) SELECT '{url}' WHERE NOT EXISTS(SELECT 1 FROM swiper WHERE url='{url}');")
 q.append(f"INSERT INTO article(type,uploadTime,title,editor,editor_id,reviewer,reviewer_id,content,review_state,likes,image_path,video_path) SELECT '支部动态',NOW(),'{esc(title)}','电光党建示例编辑','admin','本地示例审核','admin','{esc(html)}',1,0,'{url}','' WHERE NOT EXISTS(SELECT 1 FROM article WHERE title='{esc(title)}');")
q.append('COMMIT;');Path('database/demo-content.sql').write_text('\n'.join(q),encoding='utf-8')
